    "faq.k": "Yordam",
    "faq.title": "KoвЂp beriladigan savollar",
    "faq.sub": "BTT mebellari, mavjudligi va yetkazib berish haqida maвЂ™lumotlar.",
    "faq.q1": "BTT assortimentida qanday mebel toifalari mavjud?",
    "faq.a1": "Bizda 4 ta asosiy toifa mavjud: toвЂqilgan stullar (Vertex, Corda), amaliy plastik stullar (ROERO, NOERO, TODO, TODO SOFT, JARDIN), yumshoq stullar (LIRA, COMO) hamda LDSP va metall ovqat stollari (Taper, Vertex, Corda).",
    "faq.q2": "Plastik stullar qanday yuk koвЂtaradi?",
    "faq.a2": "ROERO va NOERO stullari 120 kg gacha, JARDIN modeli 150 kg gacha, TODO va TODO SOFT stullari esa 180 kg gacha yuk koвЂtaradi.",
    "faq.q3": "LDSP stollarni ochiq havoda ishlatsa boвЂladimi?",
    "faq.a3": "Stollar xonalar va usti yopiq maydonlar (ayvonlar, yopiq terrasalar, oshxonalar) uchun moвЂljallangan. LDSP ustki qismini toвЂgвЂridan-toвЂgвЂri yomgвЂirdan himoya qilish tavsiya etiladi.",
    "faq.q4": "Stullarning qaysi ranglari mavjud?",
    "faq.a4": "Bir qator modellarda ranglar tasdiqlangan: Vertex - bej, ROERO - kulrang, NOERO - kapuchino, koвЂk, toвЂq sariq va zaytun, JARDIN - kapuchino, zaytun va kulrang, TODO - qora, Vertex D90 stoli - oq marmar. Boshqa modellarda ranglarni menejerdan aniqlang.",
    "faq.q5": "Toshkent boвЂylab yetkazish qanday amalga oshiriladi?",
    "faq.a5": "Toshkent boвЂylab yetkazish 1-2 ish kunida amalga oshiriladi. Narxi buyurtma hajmiga qarab hisoblanadi.",
    "faq.q6": "Buyurtmani qanday berish mumkin?",
    "faq.a6": "Saytda savatchaga qoвЂshishingiz, +998 77 104 44 22 raqamiga qoвЂngвЂiroq qilishingiz yoki Telegram @btt_uz orqali yozishingiz mumkin.",
    "faq.q7": "Kafe va restoranlar (HoReCa) uchun buyurtma olasizmi?",
    "faq.a7": "Ha, umumiy ovqatlanish korxonalari va kafelarni toвЂliq jihozlaymiz. Maxsus hisob-kitob uchun biz bilan bogвЂlaning.",
    "faq.q8": "Mebel qanday parvarish qilinadi?",
    "faq.a8": "Plastik va toвЂqilgan yuzalar nam mato bilan oson tozalanadi. LDSP ustki qismini quruq yoki biroz namlangan yumshoq mato bilan artish yetarli.",
