    "ab.story.k": "Our story",
    "ab.story.title": "Quality furniture for everyday living",
    "ab.story.body1": "BTT provides furniture solutions for residences, patios, verandas, and dining venues. We select dependable tables and chairs that combine sturdy construction with clean modern design.",
    "ab.story.body2": "Our catalog includes wicker chairs with soft cushions, plastic chairs, comfortable upholstered chairs, and chipboard tables on metal frames.",
