    "cookie.badge": "Privacy В· 2026 Edition",
    "priv.badge": "Data Protection В· 2026 Edition",
    "seo.rotang.stockBadge": "In stock in Tashkent warehouse",
    "seo.rotang.c3.l2": "Taper Rotang 80Г-80 cm (615 000 UZS).",
    "seo.rotang.c3.l3": "Taper Rotang 135Г-80 cm (715 000 UZS).",
    "ret.step1.d": "Message us on Telegram <a href=\"https://t.me/btt_uz\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:var(--copper)\">@btt_uz</a> or call <a href=\"tel:+998771044422\" style=\"color:var(--copper)\">+998 77 104 44 22</a>.",
    "faq.k": "Help",
    "faq.title": "Frequently Asked Questions",
    "faq.sub": "Answers to common questions regarding BTT furniture, stock, delivery, and care.",
    "faq.q1": "What categories of furniture does BTT offer?",
    "faq.a1": "We carry 4 core categories: wicker chairs with cushions (Vertex, Corda), practical plastic chairs (ROERO, NOERO, TODO, TODO SOFT, JARDIN), upholstered chairs (LIRA, COMO), and chipboard dining tables (Taper, Vertex, Corda).",
    "faq.q2": "What are the load ratings for plastic chairs?",
    "faq.a2": "ROERO and NOERO chairs are rated up to 120 kg, JARDIN up to 150 kg, and TODO and TODO SOFT chairs support up to 180 kg.",
    "faq.q3": "Can chipboard tables be used outdoors?",
    "faq.a3": "These tables are designed for indoor and covered environments (verandas, covered terraces, dining rooms, cafes). We recommend protecting chipboard tabletops from direct rain and moisture.",
    "faq.q4": "Which chair colors are available?",
    "faq.a4": "Several models feature confirmed colors: Vertex in beige, ROERO in grey, NOERO in cappuccino, blue, orange, olive, JARDIN in cappuccino, olive, grey, TODO in black, Vertex D90 table in white marble. For other models, inquire with our manager.",
    "faq.q5": "How does delivery work in Tashkent?",
    "faq.a5": "Delivery in Tashkent takes 1-2 business days. The fee is calculated at direct courier rates based on destination and order volume.",
    "faq.q6": "How can I place an order?",
